import numpy as np, itertools, sys

def nrm(v):
    v=np.array(v,dtype=float); return v/np.linalg.norm(v)

def perp_frame(a):
    a=nrm(a); t=np.array([0,0,1.0])
    if abs(np.dot(a,t))>0.9: t=np.array([1.0,0,0])
    e1=nrm(np.cross(a,t)); e2=nrm(np.cross(a,e1)); return e1,e2

def tetra_dirs(a,e1,e2,phis):
    out=[]
    for p in phis:
        p=np.radians(p)
        out.append(nrm(0.3333*nrm(a)+0.9428*(np.cos(p)*e1+np.sin(p)*e2)))
    return out

