import numpy as np, itertools
from scipy.spatial.distance import cdist

def nrm(v):
    v=np.array(v,float); return v/np.linalg.norm(v)
def perp_frame(a):
    a=nrm(a); t=np.array([0,0,1.])
    if abs(np.dot(a,t))>0.9: t=np.array([1.,0,0])
    e1=nrm(np.cross(a,t)); e2=nrm(np.cross(a,e1)); return e1,e2
def tetra(a,e1,e2,phis):
    return [nrm(0.3333*nrm(a)+0.9428*(np.cos(np.radians(p))*e1+np.sin(np.radians(p))*e2)) for p in phis]

class B:
    def __init__(s): s.sym=[]; s.pos=[]; s.bonds=[]
    def add(s,sy,p,parent=None):
        s.sym.append(sy); s.pos.append(np.array(p,float))
        i=len(s.sym)-1
        if parent is not None: s.bonds.append((parent,i))
        return i
    def methyl(s,parent,cpos,axis,phi0=0.):
        a=nrm(axis); c=s.add('C',cpos,parent); e1,e2=perp_frame(a)
        for d in tetra(a,e1,e2,[phi0,phi0+120,phi0+240]): s.add('H',s.pos[c]+1.09*d,c)
        return c
    def iPr(s,parent,pos,outward,normal,phi=90):
        a=nrm(outward); ch=s.add('C',pos+1.52*a,parent)
        e1=nrm(normal); e2=nrm(np.cross(e1,a))
        ds=tetra(a,e1,e2,[phi,phi+120,phi+240])
        s.add('H',s.pos[ch]+1.10*ds[0],ch)
        for d in ds[1:]: s.methyl(ch,s.pos[ch]+1.53*d,d)
    def aryl(s,parent,ipso,u,v,ipr=False,iprphi=(90,90)):
        u=nrm(u); v=nrm(v); c=ipso+1.39*u; nn=nrm(np.cross(u,v)); idx=[]
        for ang in [180,120,60,0,-60,-120]:
            idx.append(s.add('C',c+1.39*(np.cos(np.radians(ang))*u+np.sin(np.radians(ang))*v)))
        s.bonds.append((parent,idx[0]))
        for k in range(6): s.bonds.append((idx[k],idx[(k+1)%6]))
        j=0
        for k in range(1,6):
            p=s.pos[idx[k]]; o=nrm(p-c)
            if ipr and k in (1,5):
                s.iPr(idx[k],p,o,nn,iprphi[j]); j+=1
            else: s.add('H',p+1.08*o,idx[k])

Ge=np.array([0.,0,0]); Ir=np.array([2.55,0,0]); N=np.array([0,1.85,0.]); Pp=np.array([1.70,2.12,0.])

def build(phbis, phhalf, phtw, dCl, cpphase, iprphi):
    s=B()
    iGe=s.add('Ge',Ge); iIr=s.add('Ir',Ir); iN=s.add('N',N); iP=s.add('P',Pp)
    s.bonds += [(iGe,iN),(iGe,iIr),(iN,iP),(iP,iIr),(iIr,0)][:4]
    b=nrm(nrm(N-Ge)+nrm(Ir-Ge))
    for sg in (1,-1): s.add('Cl',Ge+2.17*nrm(-b*0.70+np.array([0,0,sg*0.8])),iGe)
    uN=-nrm(nrm(Ge-N)+nrm(Pp-N))
    s.aryl(iN,N+1.43*uN,uN,np.array([0,0,1.]),ipr=True,iprphi=iprphi)
    bis=nrm(phbis); e1,e2=perp_frame(bis)
    ax=nrm(np.cross(bis,np.array([0,0,1.])))
    for sg,tw in zip((1,-1),phtw):
        ca,sa=np.cos(np.radians(phhalf)),np.sin(np.radians(phhalf))
        d=nrm(ca*bis+sa*sg*np.array([0,0,1.]))
        f1,f2=perp_frame(d)
        v=np.cos(np.radians(tw))*f1+np.sin(np.radians(tw))*f2
        s.aryl(iP,Pp+1.83*d,d,v)
    dCl=nrm(dCl); s.add('Cl',Ir+2.40*dCl,iIr)
    dcp=-nrm(nrm(Ge-Ir)+nrm(Pp-Ir)+dCl); cen=Ir+1.88*dcp
    e1,e2=perp_frame(dcp)
    ring=[]
    for k in range(5):
        t=np.radians(72*k+cpphase); r=np.cos(t)*e1+np.sin(t)*e2
        c=s.add('C',cen+1.235*r,iIr); ring.append(c)
        s.methyl(c,cen+2.75*r+0.20*dcp,r)
    for k in range(5): s.bonds.append((ring[k],ring[(k+1)%5]))
    return s

def penalty(s):
    n=len(s.sym); P=np.array(s.pos); D=cdist(P,P)
    adj=[set() for _ in range(n)]
    for i,j in s.bonds: adj[i].add(j); adj[j].add(i)
    excl=set()
    for i in range(n):
        for j in adj[i]:
            excl.add((min(i,j),max(i,j)))
            for k in adj[j]:
                if k!=i: excl.add((min(i,k),max(i,k)))
    pen=0; worst=(9,None)
    for i in range(n):
        for j in range(i+1,n):
            if (i,j) in excl: continue
            hh = s.sym[i]=='H' and s.sym[j]=='H'
            anyh = s.sym[i]=='H' or s.sym[j]=='H'
            lim = 2.0 if hh else (2.3 if anyh else 2.9)
            d=D[i,j]
            if d<lim: pen+=(lim-d)**2
            if d-lim<worst[0]-0: pass
            if d<worst[0]: worst=(d,(i,s.sym[i],j,s.sym[j]))
    return pen,worst

